        r, c = pts[0]
        for rr in range(r+1, 15):
            if d1_output[rr][c] == 0:
                d1_output[rr][c] = color
            else:
                break
    else:
        r1, c1 = pts[0]
        r2, c2 = pts[1]

        # Vertical arm: col c1 from r1 to r2
        for rr in range(min(r1,r2), max(r1,r2)+1):
            d1_output[rr][c1] = max(d1_output[rr][c1], color)

        # Horizontal arm: row r2 from c1 to c2
        for cc in range(min(c1,c2), max(c1,c2)+1):
            d1_output[r2][cc] = max(d1_output[r2][cc], color)

